            background: 'linear-gradient(180deg, #2c1810 0%, #1a0e08 100%)',
            borderRadius: 18, padding: '20px 18px', width: '100%', maxWidth: 380,
            border: '1px solid rgba(184, 134, 11, 0.3)',
